import{_ as t}from"./chunks/interactive-mode.GWxR--kb.js";import{_ as o,o as a,c as s,a2 as r}from"./chunks/framework.LX5S0jbT.js";const g=JSON.parse('{"title":"Use Pi in the terminal","description":"","frontmatter":{},"headers":[],"relativePath":"usage.md","filePath":"usage.md"}'),n={name:"usage.md"};function i(d,e,c,l,h,u){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="use-pi-in-the-terminal" tabindex="-1">Use Pi in the terminal <a class="header-anchor" href="#use-pi-in-the-terminal" aria-label="Permalink to &quot;Use Pi in the terminal&quot;">​</a></h1><p>Run <code>pi</code> from the folder you want to work in. Pi uses that folder to discover files, instructions, and configuration, and to group saved sessions. If you have not installed Pi or chosen a model yet, follow the <a href="./quickstart.html">Quickstart</a>.</p><p>Pi may ask whether you trust the working folder before loading its project resources. See <a href="./security.html#understand-project-trust">Project trust</a>.</p><p align="center"><img src="'+t+'" alt="Pi interactive mode showing a conversation, editor, and status information" width="750"></p><p>The transcript shows your prompts, Pi&#39;s responses, tool calls, results, and errors. You write prompts and commands in the editor. The footer shows the current folder, session, model, context usage, and accumulated usage and cost.</p><h2 id="enter-a-prompt" tabindex="-1">Enter a prompt <a class="header-anchor" href="#enter-a-prompt" aria-label="Permalink to &quot;Enter a prompt&quot;">​</a></h2><p>Type a request and press <code>Enter</code> to send it. Use <code>Shift+Enter</code> to add a line, or press <code>Ctrl+G</code> to work on a longer prompt in your configured external editor.</p><p>To include files or images:</p><ul><li>Type <code>@</code> to search for a file and add it to your prompt.</li><li>Press <code>Tab</code> to complete a path.</li><li>Paste an image or drag it into a compatible terminal.</li></ul><h2 id="follow-pi-s-work" tabindex="-1">Follow Pi&#39;s work <a class="header-anchor" href="#follow-pi-s-work" aria-label="Permalink to &quot;Follow Pi&#39;s work&quot;">​</a></h2><p>Pi shows each tool call and result while it works. Press <code>Ctrl+O</code> to expand or collapse tool output. Press <code>Ctrl+T</code> to show or hide thinking blocks.</p><p>The startup header lists the instructions and resources Pi loaded. The editor border indicates the current thinking level. The footer updates as the model uses context and reports usage.</p><p>Pi does not ask before every tool call. Review commands and changed files, and use a sandbox for untrusted or unattended work. See <a href="./security.html">Security</a>.</p><h2 id="change-direction" tabindex="-1">Change direction <a class="header-anchor" href="#change-direction" aria-label="Permalink to &quot;Change direction&quot;">​</a></h2><p>You can send more input while Pi is working:</p><table tabindex="0"><thead><tr><th>What you want</th><th>Action</th></tr></thead><tbody><tr><td>Adjust the current task</td><td>Type a message and press <code>Enter</code></td></tr><tr><td>Add work after the current task</td><td>Type a message and press <code>Alt+Enter</code></td></tr><tr><td>Return queued messages to the editor</td><td>Press <code>Alt+Up</code></td></tr><tr><td>Stop the current task</td><td>Press <code>Escape</code></td></tr></tbody></table><p>A message sent with <code>Enter</code> waits until the current response and its tool calls finish, then guides the next response. A follow-up sent with <code>Alt+Enter</code> waits until Pi finishes the current task. Aborting returns queued messages to the editor.</p><p>Windows Terminal reserves some Alt shortcuts. See <a href="./terminal-setup.html">Terminal Setup</a> for the Windows alternatives.</p><h2 id="change-the-model-or-settings" tabindex="-1">Change the model or settings <a class="header-anchor" href="#change-the-model-or-settings" aria-label="Permalink to &quot;Change the model or settings&quot;">​</a></h2><p>Type <code>/</code> to search the available commands. The commands you will use most often are:</p><ul><li><code>/model</code> selects a model. Press <code>Ctrl+L</code> to open the same selector.</li><li><code>/thinking</code> selects how much reasoning the current model uses. Press <code>Shift+Tab</code> to cycle through supported levels.</li><li><code>/login</code> and <code>/logout</code> manage provider access.</li><li><code>/settings</code> changes common preferences.</li></ul><p>Prompt templates, skills, and extensions can add more commands to the same menu. See <a href="./models.html">Choose a Model</a>, <a href="./configuration.html">Configuration</a>, or the complete <a href="./slash-commands.html">Slash Commands reference</a>.</p><h2 id="continue-or-start-over" tabindex="-1">Continue or start over <a class="header-anchor" href="#continue-or-start-over" aria-label="Permalink to &quot;Continue or start over&quot;">​</a></h2><p>Pi saves sessions automatically unless session persistence is disabled.</p><ul><li><code>/new</code> starts a new session.</li><li><code>/resume</code> opens another saved session.</li><li><code>/name</code> gives the current session a recognizable name.</li><li><code>/session</code> shows its file, ID, message count, token usage, and cost.</li></ul><p>Use <code>/tree</code>, <code>/fork</code>, or <code>/clone</code> when you want to explore another approach without losing existing work. Use <code>/compact</code> to reduce the conversation history sent to the model. See <a href="./sessions.html">Sessions and Context</a> for these workflows.</p><p>After leaving Pi, run <code>pi --continue</code> from the same folder to resume its most recent session.</p><h2 id="run-a-terminal-command" tabindex="-1">Run a terminal command <a class="header-anchor" href="#run-a-terminal-command" aria-label="Permalink to &quot;Run a terminal command&quot;">​</a></h2><p>Prefix a command with <code>!</code> to run it and include its output in the conversation:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!git status</span></span></code></pre></div><p>Use <code>!!</code> when you want to run a command without sending its output to the model.</p><h2 id="copy-export-or-share-results" tabindex="-1">Copy, export, or share results <a class="header-anchor" href="#copy-export-or-share-results" aria-label="Permalink to &quot;Copy, export, or share results&quot;">​</a></h2><p>Press <code>Ctrl+X</code> or run <code>/copy</code> to copy the last assistant response. Use <code>/export</code> to save the session as HTML or JSONL.</p><p>Use <code>/share</code> to upload the session and get a viewer link. By default, Radius authentication makes the artifact visible to your Radius organization; otherwise, Pi creates a private GitHub gist through the GitHub CLI. The <a href="./settings.html#sessions-and-context"><code>sessionShareDestination</code></a> setting can force either destination. Review the session first because it can contain prompts, tool output, file contents, and credentials exposed during the conversation.</p><h2 id="adjust-the-terminal" tabindex="-1">Adjust the terminal <a class="header-anchor" href="#adjust-the-terminal" aria-label="Permalink to &quot;Adjust the terminal&quot;">​</a></h2><p>Fullscreen mode, the default, keeps the editor and status area fixed while the transcript scrolls within the terminal window. Regular mode uses the terminal&#39;s normal scrollback. Choose a mode through <code>/settings</code> or <code>--tui-mode</code>.</p><p>Terminal support for mouse input, keyboard shortcuts, and inline images varies. See <a href="./terminal-setup.html">Terminal Setup</a> for platform-specific configuration and <a href="./keybindings.html">Keybindings</a> for every configurable shortcut. Run <code>/hotkeys</code> to inspect the shortcuts active in your current session.</p><h2 id="collect-diagnostic-information" tabindex="-1">Collect diagnostic information <a class="header-anchor" href="#collect-diagnostic-information" aria-label="Permalink to &quot;Collect diagnostic information&quot;">​</a></h2><p>When troubleshooting terminal rendering or conversation state, run <code>/debug</code>. Pi writes the rendered terminal lines and current session messages to <code>pi-debug.log</code> in your <a href="./configuration.html#agent-directory">agent directory</a>.</p><p>Review this file before sharing it. It can contain prompts, model responses, tool output, file contents, and terminal data.</p>',40)])])}const f=o(n,[["render",i]]);export{g as __pageData,f as default};
